insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a entidade descumprir obrigação do art. 94, aplicam-se medidas sem prejuízo da responsabilidade civil e criminal de seus dirigentes. Às governamentais: advertência, afastamento provisório ou definitivo dos dirigentes e fechamento de unidade ou interdição de programa. Às não governamentais: advertência, suspensão total ou parcial do repasse de verbas públicas, interdição de unidades ou suspensão de programa e cassação do registro.', '["Medidas para entidades governamentais.","Medidas para não governamentais.","Responsabilidade civil e criminal dos dirigentes."]'::jsonb, '["Medidas diferentes conforme a natureza da entidade.","Cassação do registro é medida das não governamentais."]'::jsonb, 'A ONG que descumpre obrigações pode perder o registro.', '["Assertiva que prevê afastamento de dirigentes de entidades não governamentais nesse artigo erra: é medida das governamentais."]'::jsonb, '[]'::jsonb, '["Art. 94"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-97'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas de proteção à criança e ao adolescente são aplicáveis sempre que os direitos reconhecidos no Estatuto forem ameaçados ou violados por ação ou omissão da sociedade ou do Estado, por falta, omissão ou abuso dos pais ou responsável, ou em razão da própria conduta da criança ou adolescente.', '["Ameaça ou violação de direitos.","Três situações de risco."]'::jsonb, '["Três hipóteses: sociedade/Estado, pais, conduta própria."]'::jsonb, 'A criança em situação de rua recebe medidas de proteção.', '["Assertiva que restringe a proteção aos casos de falta dos pais erra."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-98'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas de proteção podem ser aplicadas isolada ou cumulativamente, bem como substituídas a qualquer tempo.', '["Aplicação isolada ou cumulativa.","Substituição a qualquer tempo."]'::jsonb, '["Flexibilidade na aplicação."]'::jsonb, 'O juiz soma a matrícula escolar e o acompanhamento temporário.', '["Assertiva que veda a cumulação de medidas de proteção erra."]'::jsonb, '[]'::jsonb, '["Art. 100"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-99'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na aplicação das medidas levam-se em conta as necessidades pedagógicas, preferindo-se as que fortaleçam os vínculos familiares e comunitários. Entre os princípios que regem as medidas estão a condição da criança como sujeito de direitos, a proteção integral e prioritária, a responsabilidade primária e solidária do poder público, o interesse superior da criança, a privacidade, a intervenção precoce e mínima, a proporcionalidade, a atualidade, a responsabilidade parental, a prevalência da família e a obrigatoriedade da informação e da oitiva.', '["Preferência pelas medidas que fortalecem os vínculos.","Princípios: sujeito de direitos, proteção integral, interesse superior, privacidade.","Intervenção precoce e mínima, proporcionalidade, prevalência da família.","Obrigatoriedade da informação e da oitiva."]'::jsonb, '["ATUALIZAÇÃO: os princípios do parágrafo único vieram da Lei de Adoção.","Interesse superior e prevalência da família são princípios centrais."]'::jsonb, 'O juiz prefere manter a criança na família com apoio, em vez de acolhê-la.', '["Assertiva que prefere o afastamento familiar às medidas de fortalecimento de vínculos erra."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-100'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificadas as hipóteses do art. 98, a autoridade competente pode determinar, entre outras, as medidas de encaminhamento aos pais mediante termo de responsabilidade, orientação e apoio temporários, matrícula e frequência obrigatórias em ensino fundamental, inclusão em programas de proteção à família, requisição de tratamento médico, psicológico ou psiquiátrico, inclusão em programa de auxílio a dependentes, acolhimento institucional, inclusão em programa de acolhimento familiar e colocação em família substituta. O acolhimento é medida provisória e excepcional, sem privação de liberdade, e depende de ordem judicial, com plano individual de atendimento.', '["Rol de medidas de proteção.","Acolhimento institucional e familiar: provisório e excepcional.","Colocação em família substituta.","Plano individual de atendimento."]'::jsonb, '["ATUALIZAÇÃO: acolhimento institucional e plano individual de atendimento vieram da Lei de Adoção.","Acolhimento NÃO é privação de liberdade.","Acolhimento depende, em regra, de ordem judicial."]'::jsonb, 'A criança em risco é acolhida e a família é incluída em programa de apoio.', '["Assertiva que considera o acolhimento institucional uma forma de privação de liberdade erra."]'::jsonb, '[{"termo":"Plano Individual de Atendimento","significado":"Documento que organiza as ações para a reintegração familiar da criança acolhida."}]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-101'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas de proteção são acompanhadas da regularização do registro civil. Se não houver registro anterior, o assento de nascimento é feito à vista dos elementos disponíveis, mediante requisição da autoridade judiciária. Os registros e certidões necessários são isentos de multas, custas e emolumentos, com absoluta prioridade. Se a paternidade ainda não estiver definida, o procedimento próprio será adotado.', '["Regularização do registro civil.","Assento à vista dos elementos disponíveis.","Isenção de custas e emolumentos.","Procedimento para definir a paternidade."]'::jsonb, '["Registros e certidões são ISENTOS de custas e emolumentos."]'::jsonb, 'A criança sem registro tem o nascimento regularizado sem custo.', '["Assertiva que cobra emolumentos pela regularização do registro civil erra."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
