on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se ato infracional a conduta descrita como crime ou contravenção penal.', '["Ato infracional = crime ou contravenção penal praticada por criança ou adolescente."]'::jsonb, '["Vocabulário próprio: não se fala em crime do adolescente, e sim em ato infracional."]'::jsonb, 'O furto praticado por adolescente é ato infracional.', '["Assertiva que trata o ato infracional como crime do adolescente erra na terminologia legal."]'::jsonb, '[{"termo":"Ato infracional","significado":"Conduta descrita como crime ou contravenção penal."}]'::jsonb, '["Art. 104"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-103'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São penalmente inimputáveis os menores de dezoito anos, sujeitos às medidas previstas no Estatuto. Para os efeitos da lei, considera-se a idade do adolescente à data do fato.', '["Inimputabilidade penal dos menores de dezoito anos.","Idade considerada à data do fato."]'::jsonb, '["Idade à data do FATO, não do julgamento."]'::jsonb, 'O jovem que praticou o ato aos dezessete anos responde pelo Estatuto, mesmo julgado aos dezenove.', '["Assertiva que considera a idade na data da sentença erra: vale a idade na data do fato."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
