insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao ato infracional praticado por criança correspondem as medidas de proteção previstas no art. 101, e não medidas socioeducativas.', '["Criança: medidas de proteção do art. 101."]'::jsonb, '["Criança não recebe medida socioeducativa."]'::jsonb, 'A criança de dez anos que furta recebe medida de proteção.', '["Assertiva que aplica medida socioeducativa de internação à criança erra."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-105'
