insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A apreensão de qualquer adolescente e o local onde se encontra recolhido são comunicados imediatamente à autoridade judiciária competente e à família do apreendido ou à pessoa por ele indicada. Examina-se desde logo, sob pena de responsabilidade, a possibilidade de liberação imediata.', '["Comunicação imediata ao juiz e à família.","Exame de liberação imediata, sob pena de responsabilidade."]'::jsonb, '["Comunicação IMEDIATA."]'::jsonb, 'A polícia avisa o juiz e a mãe do adolescente apreendido.', '["Assertiva que dispensa a comunicação à família do apreendido erra."]'::jsonb, '[]'::jsonb, '["Art. 106"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-107'
