insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A internação antes da sentença pode ser determinada pelo prazo máximo de quarenta e cinco dias. A decisão deve ser fundamentada e basear-se em indícios suficientes de autoria e materialidade, demonstrada a necessidade imperiosa da medida.', '["Internação provisória por até quarenta e cinco dias.","Decisão fundamentada.","Indícios de autoria e materialidade e necessidade imperiosa."]'::jsonb, '["Prazo máximo de quarenta e cinco dias."]'::jsonb, 'O adolescente fica internado provisoriamente por até quarenta e cinco dias.', '["Assertiva que fixa em noventa dias o prazo da internação provisória erra: são quarenta e cinco dias."]'::jsonb, '[{"termo":"Internação provisória","significado":"Privação de liberdade antes da sentença, por prazo máximo de quarenta e cinco dias."}]'::jsonb, '["Art. 183"]'::jsonb, 'under_review', 'claude'
