insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum adolescente será privado de sua liberdade sem o devido processo legal.', '["Devido processo legal."]'::jsonb, '["Garantia constitucional aplicada ao adolescente."]'::jsonb, 'A internação como medida socioeducativa só ocorre depois do processo.', '["Assertiva que dispensa o devido processo na apuração do ato infracional erra."]'::jsonb, '[]'::jsonb, '["Art. 111"]'::jsonb, 'under_review', 'claude'
