insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada a prática de ato infracional, a autoridade pode aplicar ao adolescente advertência, obrigação de reparar o dano, prestação de serviços à comunidade, liberdade assistida, inserção em regime de semiliberdade, internação em estabelecimento educacional ou qualquer das medidas de proteção do art. 101, incisos I a VI. A medida leva em conta a capacidade de cumpri-la, as circunstâncias e a gravidade da infração. Em hipótese alguma e sob pretexto algum será admitida a prestação de trabalho forçado, e os adolescentes portadores de doença ou deficiência mental recebem tratamento individual e especializado.', '["Seis medidas socioeducativas e as protetivas.","Capacidade de cumprimento, circunstâncias e gravidade.","Vedado o trabalho forçado.","Tratamento especializado para doença ou deficiência mental."]'::jsonb, '["Rol de medidas socioeducativas: advertência, reparação, serviços, liberdade assistida, semiliberdade e internação.","Trabalho forçado é vedado em qualquer hipótese."]'::jsonb, 'O juiz aplica prestação de serviços à comunidade ao adolescente que cometeu ato de menor gravidade.', '["Assertiva que admite o trabalho forçado como medida socioeducativa erra."]'::jsonb, '[{"termo":"Medida socioeducativa","significado":"Resposta estatal ao ato infracional do adolescente, com finalidade pedagógica."}]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
