insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A imposição das medidas dos incisos II a VI do art. 112 pressupõe a existência de provas suficientes da autoria e da materialidade, ressalvada a hipótese de remissão. A advertência pode ser aplicada sempre que houver prova da materialidade e indícios suficientes da autoria.', '["Provas suficientes de autoria e materialidade.","Advertência exige menos: materialidade e indícios de autoria."]'::jsonb, '["Advertência: prova da materialidade e INDÍCIOS de autoria."]'::jsonb, 'Para a advertência bastam prova do fato e indícios de quem o praticou.', '["Assertiva que exige prova plena de autoria para a advertência erra: bastam indícios suficientes."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
