insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A advertência consiste em admoestação verbal, que é reduzida a termo e assinada.', '["Admoestação verbal.","Reduzida a termo e assinada."]'::jsonb, '["Verbal, mas documentada."]'::jsonb, 'O juiz adverte o adolescente e lavra o termo assinado.', '["Assertiva que dispensa a redução a termo da advertência erra."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
