insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em cada Município e em cada Região Administrativa do Distrito Federal haverá, no mínimo, um Conselho Tutelar como órgão integrante da administração pública local, composto de cinco membros, escolhidos pela população local para mandato de quatro anos, permitida recondução por novos processos de escolha.', '["Ao menos um Conselho Tutelar por Município.","Cinco membros.","Mandato de quatro anos.","Recondução por novo processo de escolha."]'::jsonb, '["Cinco membros, mandato de quatro anos.","ATUALIZAÇÃO: o mandato foi ampliado de três para quatro anos por lei posterior.","A recondução exige NOVO processo de escolha."]'::jsonb, 'A população elege cinco conselheiros tutelares para um mandato de quatro anos.', '["Assertiva que fixa o mandato em três anos erra: são quatro anos."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
