insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedada a divulgação de atos judiciais, policiais e administrativos relativos a crianças e adolescentes a quem se atribua ato infracional. Qualquer notícia sobre o fato não pode identificar a criança ou adolescente, sendo proibidas fotografia, referência a nome, apelido, filiação, parentesco, residência e, inclusive, iniciais do nome e sobrenome.', '["Vedada a divulgação de atos sobre ato infracional.","Proibida a identificação, inclusive por iniciais."]'::jsonb, '["Vedadas até as INICIAIS do nome e sobrenome."]'::jsonb, 'A reportagem não pode divulgar o nome nem as iniciais do adolescente.', '["Assertiva que permite divulgar as iniciais do adolescente erra."]'::jsonb, '[]'::jsonb, '["Art. 247"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-143'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A expedição de cópia ou certidão dos atos de que trata o artigo anterior só é deferida pela autoridade judiciária competente, se demonstrado o interesse e justificada a finalidade.', '["Cópia ou certidão só com autorização judicial.","Exige interesse demonstrado e finalidade justificada."]'::jsonb, '["Depende de decisão da autoridade judiciária."]'::jsonb, 'A certidão do processo só é fornecida mediante autorização do juiz.', '["Assertiva que permite ao escrivão fornecer certidão a qualquer interessado erra."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-144'
