insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os estados e o Distrito Federal podem criar varas especializadas e exclusivas da infância e da juventude, cabendo ao Poder Judiciário estabelecer sua proporcionalidade por número de habitantes, dotá-las de infraestrutura e dispor sobre o atendimento, inclusive em plantões.', '["Varas especializadas e exclusivas.","Proporcionalidade por número de habitantes.","Atendimento em plantões."]'::jsonb, '["Faculdade dos estados e do Distrito Federal."]'::jsonb, 'O tribunal cria vara exclusiva da infância em comarca populosa.', '["Assertiva que obriga a criação de vara da infância em todas as comarcas erra: é faculdade."]'::jsonb, '[]'::jsonb, '["Art. 146"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-145'
