insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência é determinada pelo domicílio dos pais ou responsável ou, à falta destes, pelo lugar onde se encontre a criança ou adolescente. Nos atos infracionais, é competente a autoridade do lugar da ação ou omissão, observadas as regras de conexão, continência e prevenção. A execução das medidas pode ser delegada à autoridade da residência dos pais ou do local da entidade. As ações de adoção e as de crianças em acolhimento observam regras próprias.', '["Domicílio dos pais ou responsável.","À falta, lugar onde está a criança.","Ato infracional: lugar da ação ou omissão.","Execução delegável."]'::jsonb, '["Ato infracional: competência do lugar da AÇÃO ou OMISSÃO.","A execução pode ser delegada."]'::jsonb, 'O ato infracional é julgado no local onde ocorreu.', '["Assertiva que fixa o domicílio do adolescente como competência no ato infracional erra: é o lugar da ação ou omissão."]'::jsonb, '[]'::jsonb, '["Art. 148"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-147'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Justiça da Infância e da Juventude é competente para conhecer de representações do Ministério Público para apuração de ato infracional, conceder a remissão como forma de suspensão ou extinção do processo, conhecer de pedidos de adoção e seus incidentes, conhecer de ações civis fundadas em interesses individuais, difusos ou coletivos afetos à criança e ao adolescente, ações decorrentes de irregularidades em entidades de atendimento, aplicar penalidades administrativas por infrações às normas de proteção e conhecer de casos encaminhados pelo Conselho Tutelar. Em relação a crianças e adolescentes, também conhece de pedidos de guarda, tutela, destituição, suprimento de consentimento para casamento e alvarás.', '["Apuração de ato infracional.","Remissão judicial.","Adoção e incidentes.","Ações civis de interesse da infância.","Penalidades administrativas.","Guarda, tutela, destituição e outros pedidos."]'::jsonb, '["Alimentos e guarda em disputa entre pais ficam, em regra, na vara de família, salvo situação de risco.","O rol é amplo; vale conferir o art. 148 para as hipóteses em que a vara da infância é competente."]'::jsonb, 'A Vara da Infância processa o pedido de adoção.', '["Assertiva que atribui à Vara da Infância toda disputa de guarda entre pais separados erra."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-148'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à autoridade judiciária disciplinar, por portaria, ou autorizar, mediante alvará, a entrada e permanência de criança ou adolescente, desacompanhado dos pais, em estádios, bailes, boates, casas de diversões eletrônicas e estúdios; e a participação de criança e adolescente em espetáculos públicos e seus ensaios e em certames de beleza. A portaria deve ser fundamentada, caso a caso, vedadas as determinações de caráter geral.', '["Portaria ou alvará para entrada em locais de diversão.","Participação em espetáculos e certames.","Fundamentação caso a caso."]'::jsonb, '["Vedadas as determinações de caráter GERAL: a decisão é caso a caso."]'::jsonb, 'O juiz autoriza, por alvará, a participação de uma criança em peça teatral.', '["Assertiva que permite ao juiz proibir, de modo geral e abstrato, a entrada de adolescentes em eventos erra: é caso a caso."]'::jsonb, '[{"termo":"Alvará judicial","significado":"Autorização individual concedida pelo juiz para um caso específico."}]'::jsonb, '["Art. 258"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-149'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cabe ao Poder Judiciário, na elaboração de sua proposta orçamentária, prever recursos para a manutenção de equipe interprofissional destinada a assessorar a Justiça da Infância e da Juventude.', '["Previsão orçamentária pelo Poder Judiciário.","Equipe interprofissional de assessoria."]'::jsonb, '["O encargo é do PODER JUDICIÁRIO."]'::jsonb, 'O tribunal reserva verba para contratar psicólogos e assistentes sociais.', '["Assertiva que atribui ao Executivo o custeio da equipe interprofissional da Vara erra."]'::jsonb, '[]'::jsonb, '["Art. 151"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-150'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à equipe interprofissional fornecer subsídios por escrito, mediante laudos, ou verbalmente, na audiência, e desenvolver trabalhos de aconselhamento, orientação, encaminhamento e prevenção, sob a imediata subordinação à autoridade judiciária, assegurada a livre manifestação do ponto de vista técnico. Na ausência ou insuficiência de servidores públicos integrantes do Poder Judiciário responsáveis pela realização dos estudos psicossociais, a autoridade judiciária poderá proceder à nomeação de perito.', '["Laudos e manifestação oral.","Aconselhamento, orientação e prevenção.","Subordinação ao juiz com liberdade técnica.","Nomeação de perito se faltarem servidores."]'::jsonb, '["Liberdade de manifestação do ponto de vista TÉCNICO.","ATUALIZAÇÃO: parágrafo único incluído por lei posterior."]'::jsonb, 'A psicóloga da vara apresenta laudo ao juiz e defende seu ponto de vista técnico.', '["Assertiva que sujeita o parecer técnico à opinião do juiz erra: há livre manifestação técnica."]'::jsonb, '[]'::jsonb, '["Art. 150"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-151'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos procedimentos do Estatuto aplicam-se subsidiariamente as normas gerais da legislação processual pertinente. Há prioridade absoluta na tramitação dos processos e na execução de atos e diligências judiciais, sob pena de responsabilidade. Os prazos do Estatuto são contados em dias corridos, excluído o dia do começo e incluído o do vencimento, vedado o prazo em dobro para a Fazenda Pública e o Ministério Público.', '["Aplicação subsidiária da legislação processual.","Prioridade absoluta na tramitação.","Prazos em dias corridos.","Sem prazo em dobro para Fazenda Pública e Ministério Público."]'::jsonb, '["ATUALIZAÇÃO: prazos em dias corridos, sem prazo em dobro, vieram de lei posterior.","Prioridade ABSOLUTA, sob pena de responsabilidade."]'::jsonb, 'O prazo do Ministério Público não é contado em dobro nos processos do Estatuto.', '["Assertiva que prevê prazo em dobro para o Ministério Público nos procedimentos do Estatuto erra."]'::jsonb, '[]'::jsonb, '["Art. 214"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-152'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a medida judicial a ser adotada não corresponder a procedimento previsto no Estatuto ou em outra lei, a autoridade judiciária pode investigar os fatos e ordenar de ofício as providências necessárias, ouvido o Ministério Público. Isso não se aplica ao afastamento da criança ou do adolescente de sua família de origem nem a outros procedimentos necessariamente contenciosos.', '["Poder de investigação e providências de ofício, ouvido o Ministério Público.","Exceção: afastamento da família de origem e procedimentos contenciosos."]'::jsonb, '["ATUALIZAÇÃO: parágrafo único limitou a atuação de ofício.","Não vale para afastar a criança da família de origem."]'::jsonb, 'O juiz pode determinar de ofício providências em situação sem rito próprio, exceto afastar a criança da família.', '["Assertiva que permite ao juiz afastar a criança da família de origem de ofício erra."]'::jsonb, '[]'::jsonb, '["Art. 152"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-153'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplica-se às multas o disposto no art. 214, ou seja, o produto das multas reverte ao fundo municipal dos direitos da criança e do adolescente.', '["Regime das multas segue o art. 214."]'::jsonb, '["Destino das multas: fundo municipal."]'::jsonb, 'A multa aplicada a um estabelecimento vai para o fundo dos direitos da criança.', '["Assertiva que destina as multas ao Tesouro Nacional erra."]'::jsonb, '[]'::jsonb, '["Art. 214"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-154'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O procedimento para a perda ou a suspensão do poder familiar tem início por provocação do Ministério Público ou de quem tenha legítimo interesse.', '["Legitimidade: Ministério Público ou quem tenha legítimo interesse."]'::jsonb, '["Não se inicia de ofício."]'::jsonb, 'O promotor ajuíza ação de destituição do poder familiar.', '["Assertiva que permite ao juiz iniciar de ofício a perda do poder familiar erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-155'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A petição inicial indica a autoridade judiciária a que é dirigida; o nome, estado civil, profissão e residência do requerente e do requerido, dispensada a qualificação quando o pedido for formulado pelo Ministério Público; a exposição sumária do fato e o pedido; e as provas a produzir, com o rol de testemunhas e documentos.', '["Autoridade, qualificação, fato e pedido, provas.","Dispensa de qualificação quando o autor é o Ministério Público."]'::jsonb, '["Rol de testemunhas e documentos já na inicial."]'::jsonb, 'A inicial indica desde logo as testemunhas e documentos.', '["Assertiva que dispensa o rol de testemunhas na petição inicial erra."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-156'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Havendo motivo grave, a autoridade judiciária, ouvido o Ministério Público, pode decretar a suspensão do poder familiar, liminar ou incidentalmente, até o julgamento definitivo da causa, ficando a criança confiada a pessoa idônea mediante termo de responsabilidade. Recebida a inicial, o juiz determina, independentemente de requerimento, a realização de estudo social ou perícia por equipe interprofissional, e, se a criança ainda não tiver sido ouvida, a oitiva.', '["Suspensão liminar do poder familiar por motivo grave.","Criança confiada a pessoa idônea.","Estudo social ou perícia determinados de ofício."]'::jsonb, '["Exige MOTIVO GRAVE e oitiva do Ministério Público."]'::jsonb, 'O juiz suspende liminarmente o poder familiar e confia a criança a um parente idôneo.', '["Assertiva que dispensa a oitiva do Ministério Público na suspensão liminar erra."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-157'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O requerido é citado para, no prazo de dez dias, oferecer resposta escrita, indicando as provas e oferecendo o rol de testemunhas e documentos. A citação é pessoal, salvo se esgotados todos os meios, e o requerido privado de liberdade deve ser citado pessoalmente. Quando o oficial de justiça procurar duas vezes o citando sem encontrá-lo, deverá comunicar o fato ao juiz, e a citação por edital observa regras próprias.', '["Prazo de dez dias para resposta.","Citação pessoal, inclusive do preso.","Citação por edital em último caso."]'::jsonb, '["Prazo de dez dias.","Requerido preso: citação pessoal."]'::jsonb, 'O pai preso é citado pessoalmente para responder à ação.', '["Assertiva que fixa em quinze dias o prazo de resposta erra: são dez dias."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-158'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o requerido não tiver possibilidade de constituir advogado sem prejuízo do próprio sustento e de sua família, pode requerer em cartório a nomeação de dativo, a quem incumbe apresentar a resposta, contando-se o prazo a partir da intimação do despacho de nomeação. Se o requerido estiver privado de liberdade, o oficial de justiça pergunta, no momento da citação, se deseja que lhe seja nomeado defensor.', '["Advogado dativo para quem não pode custear defensor.","Prazo conta da intimação da nomeação.","Pergunta ao requerido preso no ato da citação."]'::jsonb, '["O oficial de justiça pergunta ao preso se deseja defensor."]'::jsonb, 'O pai sem recursos pede um advogado dativo em cartório.', '["Assertiva que dispensa a pergunta ao requerido preso sobre a nomeação de defensor erra."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-159'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sendo necessário, a autoridade judiciária requisita de qualquer repartição ou órgão público a apresentação de documento que interesse à causa, de ofício ou a requerimento das partes ou do Ministério Público.', '["Requisição de documentos a órgãos públicos.","De ofício ou a requerimento."]'::jsonb, '["Possível de ofício."]'::jsonb, 'O juiz requisita ao hospital o prontuário da criança.', '["Assertiva que depende de requerimento das partes para requisitar documentos erra: pode ser de ofício."]'::jsonb, '[]'::jsonb, '["Art. 157"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-160'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se não for contestado o pedido e tiver sido concluído o estudo social ou a perícia, a autoridade judiciária dá vista dos autos ao Ministério Público por cinco dias, salvo quando este for o requerente, e decide em igual prazo. O juiz pode determinar a oitiva de testemunhas que comprovem a presença de uma das causas de suspensão ou destituição. Se o pedido importar em modificação de guarda, ouve-se a criança, sempre que possível, e considera-se sua opinião.', '["Sem contestação: vista ao Ministério Público por cinco dias.","Decisão em igual prazo.","Oitiva de testemunhas e da criança."]'::jsonb, '["Cinco dias para o Ministério Público e para a decisão."]'::jsonb, 'Sem contestação, o promotor tem cinco dias para se manifestar.', '["Assertiva que fixa em dez dias a vista ao Ministério Público erra: são cinco dias."]'::jsonb, '[]'::jsonb, '["Art. 162"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-161'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentada a resposta, a autoridade judiciária dá vista dos autos ao Ministério Público por cinco dias, salvo quando este for o requerente, designando desde logo audiência de instrução e julgamento. Na audiência, presentes as partes e o Ministério Público, são ouvidas as testemunhas, colhendo-se oralmente o parecer técnico, salvo se apresentado por escrito, e manifestam-se sucessivamente o requerente, o requerido e o Ministério Público. A decisão é proferida na audiência ou no prazo legal.', '["Vista ao Ministério Público por cinco dias.","Audiência de instrução e julgamento.","Oitiva de testemunhas e parecer técnico.","Manifestação sucessiva das partes."]'::jsonb, '["Cinco dias para o Ministério Público."]'::jsonb, 'Após a contestação, o juiz marca a audiência de instrução.', '["Assertiva que dispensa a audiência de instrução na perda do poder familiar contestada erra."]'::jsonb, '[]'::jsonb, '["Art. 161"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-162'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O prazo máximo para conclusão do procedimento de perda ou suspensão do poder familiar é de cento e vinte dias. No caso de notória inviabilidade de manutenção do poder familiar, o juiz dirige esforços para preparar a criança ou o adolescente com vistas à colocação em família substituta. A sentença que decretar a perda ou a suspensão é averbada à margem do registro de nascimento.', '["Prazo máximo de cento e vinte dias.","Preparação para família substituta se inviável a manutenção.","Averbação da sentença no registro de nascimento."]'::jsonb, '["ATUALIZAÇÃO: prazo de cento e vinte dias fixado pela Lei de Adoção.","Sentença averbada à margem do registro."]'::jsonb, 'A ação de destituição deve ser concluída em até cento e vinte dias.', '["Assertiva que fixa em noventa dias o prazo máximo do procedimento erra: são cento e vinte dias."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-163'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

